import{z as A,x as o,o as l,c as s,q as r,j as n,D as t,d as E,s as i,S as p,b as e}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"接受长度调度","description":"","frontmatter":{"title":"接受长度调度","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/acceptance-length-sched.md","filePath":"llm/acceptance-length-sched.md","lastUpdated":1791063341000}'),h={name:"llm/acceptance-length-sched.md"};function B(d,a,C,u,g,c){const m=o("Mermaid");return l(),s("div",null,[a[2]||(a[2]=r('<h1 id="接受长度调度" tabindex="-1">接受长度调度 <a class="header-anchor" href="#接受长度调度" aria-label="Permalink to &quot;接受长度调度&quot;">​</a></h1><div class="epigraph"><p>一轮投机的期望前进长度是接受率与草稿深度的函数；调度器若假装每条请求每步都只走一个 token，连续批的槽位、KV 与超时都会按最慢的那条链对齐。</p><footer>—— Leviathan 等给出的 $\\tau=(1-\\alpha^{\\gamma+1})/(1-\\alpha)$；调度要把 $\\tau$ 当成每轮的资源需求</footer></div><p>投机解码把「一步一个 token」变成「一轮前进随机个 token」。Leviathan、Kalman、Matias 在独立同分布接受率 \\(\\alpha\\)、草稿长度 \\(\\gamma\\) 下写出期望接受长度（含拒绝后的修正 token）</p> \\[\\tau=\\sum_{i=0}^{\\gamma}\\alpha^{i}=\\frac{1-\\alpha^{\\gamma+1}}{1-\\alpha}. \\]<p>\\(\\tau\\) 落在 \\([1,\\gamma+1]\\)。墙钟加速大约是 \\(\\tau\\) 除以「一轮里目标前向相对自回归一步的代价」，再扣掉草稿成本。连续批、PD 分离、MTP 闭环一旦进入生产，调度器必须看见 \\(\\tau\\)：它决定每轮占用的解码步、校验算力、以及批内参差。本篇写如何用接受长度做调度，而不是再推一遍拒绝采样公式；闭环步骤见 <a href="/llm/mtp-verify-loop">MTP 验证闭环</a>。</p><p><span class="marginnote">数字实例：\\(\\alpha=0.8\\)、\\(\\gamma=4\\) 时，\\(\\tau=(1-0.8^5)/(1-0.8)=4.4\\)，平均一轮前进约 4.4 个 token；若 \\(\\alpha\\) 跌到 0.5，同样 \\(\\gamma=4\\) 只剩 \\(\\tau\\approx1.94\\)，五个草稿大半白算。同一个 \\(\\gamma\\) 在不同流量上的收益能差一倍多，这就是 \\(\\gamma\\) 必须按请求调的原因。</span></p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>普通连续批按「本 iter 每条请求一个新 token」切预算。投机开启后，同一 iter 有的请求接受了 \\(\\gamma\\) 个草稿，有的第一个就拒绝，只写出修正 token。若仍按最慢请求切齐，快请求的超额进度要么丢掉（浪费），要么写入 KV 导致批内长度分叉，注意力核要处理更歪的块表。若完全不对齐，长接受的请求会在一轮里吃掉大量校验 FLOPs，把短请求的 TPOT 打穿。</p><p><span class="marginnote">投机解码可以类比成「学徒起草稿、师傅批改」：学徒（草稿模型）一口气写几个字，师傅（目标模型）一次核对一整段——对的照收，错处之后的全部作废、由师傅补一个修正字。核对一段只花师傅「看一遍」的功夫，比亲自逐字写快；前提是学徒猜得够准，这就是接受率 \\(\\alpha\\) 决定一切的原因。</span></p><p>\\(\\alpha\\) 不是常数。模板、代码、系统提示高，开放对话、高温度低。Leviathan 等还把 \\(\\alpha\\) 连到 \\(p\\) 与 \\(q\\) 的散度。同一模型在同一服务上，不同请求的 \\(\\tau\\) 可以差一倍。固定 \\(\\gamma\\) 会在低 \\(\\alpha\\) 时净亏损：草稿与校验开销买不回 \\(\\tau\\approx 1\\)。调度要同时选：这条请求要不要投机、\\(\\gamma\\) 取多少、本批如何混排。</p><h3 id="期望不是实现值" tabindex="-1">期望不是实现值 <a class="header-anchor" href="#期望不是实现值" aria-label="Permalink to &quot;期望不是实现值&quot;">​</a></h3><p>\\(\\tau\\) 是期望。尾部会出现连续拒绝（\\(\\tau\\) 近 1）和连中（\\(\\tau=\\gamma+1\\)）。SLO 若写 p99 TPOT，必须按最坏接受路径留校验算力，或对低 \\(\\alpha\\) 请求降 \\(\\gamma\\)。用均值 \\(\\tau\\) 做容量规划会在坏主题上超时。监控应同时报逐步 \\(\\alpha\\)、每轮实现的接受长度、以及「因投机净亏损」的比例。</p><p><span class="marginnote">公式假定各位置 \\(\\alpha\\) 独立同分布。真实序列上，一旦草稿走偏，后续更容易拒绝，有效 \\(\\tau\\) 小于 i.i.d. 预测。EAGLE-2 用草稿置信度动态长树，正是放弃「深度处处同一 \\(\\alpha\\)」。调度器若只喂一个全局 \\(\\alpha\\)，会在难前缀上过度投机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><h3 id="按请求调节" tabindex="-1">按请求调节 \\(\\gamma\\) <a class="header-anchor" href="#按请求调节" aria-label="Permalink to &quot;按请求调节 $\\gamma$&quot;">​</a></h3><p>短请求、低 \\(\\alpha\\) 估计、已经接近最大生成长度时，取 \\(\\gamma=0\\)（关掉投机）或 \\(\\gamma=1\\)。MTP \\(D=1\\) 天然 \\(\\gamma=1\\)，调节空间小，但仍可按主题开关。独立草稿模型或 EAGLE 树可以在 \\(\\gamma\\) 上做一维搜索：目标是最大化 \\(\\tau/(c_{\\mathrm{tgt}}+c_{\\mathrm{draft}}(\\gamma))\\)，其中 \\(c_{\\mathrm{tgt}}\\) 是一次校验前向相对单步解码的倍数（近似 1，但树节点多时大于 1）。\\(\\alpha\\) 可用近期滑动窗口、草稿 softmax 置信度（EAGLE-2 的经验）或主题分类器估计。</p><p>批级：优先把「预期 \\(\\tau\\) 接近」的请求放进同一微批，减少参差。无法分开时，校验核按树或链的最大深度开，短请求用掩码提前结束，避免为空气算注意力。Hydragen 式共享前缀批处理在「许多请求同一系统提示、各自投机」时有效，但接受长度仍按请求提交。</p><h3 id="把-折算成槽位" tabindex="-1">把 \\(\\tau\\) 折算成槽位 <a class="header-anchor" href="#把-折算成槽位" aria-label="Permalink to &quot;把 $\\tau$ 折算成槽位&quot;">​</a></h3><p>解码池的并发上限常按 HBM 里 KV 体积。投机不增加最终序列长度的期望（无损时与自回归同分布），但<strong>峰值</strong> KV 会含未提交的草稿节点；拒绝后要释放。调度应按 \\(\\gamma\\) 预留草稿缓冲，否则高峰时 OOM。吞吐规划用有效 token/s \\(\\approx \\mathrm{iters}\\times \\bar\\tau\\)，而不是 \\(\\mathrm{iters}\\times\\) 批大小。PD 分离时，投机几乎全在解码侧；预填充池不必为 \\(\\gamma\\) 扩容。</p>',19)),(l(),n(p,null,{default:t(()=>[i(m,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E8%AF%B7%E6%B1%82%E5%85%A5%E9%98%9F%22%5D%20--%3E%20EST%5B%22%E4%BC%B0%E8%AE%A1%20%CE%B1%E3%80%81%E9%80%89%20%CE%B3%22%5D%0A%20%20EST%20--%3E%20G%7B%22%CF%84%20%E6%98%AF%E5%90%A6%E5%A4%A7%E4%BA%8E%E6%88%90%E6%9C%AC%E9%98%88%E5%80%BC%22%7D%0A%20%20G%20--%3E%7C%22%E5%90%A6%22%7C%20AR%5B%22%E8%87%AA%E5%9B%9E%E5%BD%92%E4%B8%80%E6%AD%A5%22%5D%0A%20%20G%20--%3E%7C%22%E6%98%AF%22%7C%20SP%5B%22%E8%8D%89%E7%A8%BF%20%2B%20%E6%A0%A1%E9%AA%8C%22%5D%0A%20%20SP%20--%3E%20ACC%5B%22%E5%AE%9E%E7%8E%B0%E6%8E%A5%E5%8F%97%E9%95%BF%E5%BA%A6%20L%22%5D%0A%20%20ACC%20--%3E%20KV%5B%22%E5%8F%AA%E6%8F%90%E4%BA%A4%20L%20%E4%B8%AA%20token%22%5D%0A%20%20AR%20--%3E%20KV%0A%20%20KV%20--%3E%20NEXT%5B%22%E4%B8%8B%E4%B8%80%E8%BD%AE%E6%8C%89%E6%96%B0%E5%89%8D%E7%BC%80%E5%86%8D%E4%BC%B0%E8%AE%A1%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("h3",{id:"为什么-有最优值",tabindex:"-1"},[E("为什么 \\(\\gamma\\) 有最优值 "),e("a",{class:"header-anchor",href:"#为什么-有最优值","aria-label":'Permalink to "为什么 $\\gamma$ 有最优值"'},"​")],-1)),a[5]||(a[5]=e("p",null,"\\(\\tau(\\gamma)\\) 随 \\(\\gamma\\) 递增但边际递减：\\(\\alpha\\lt 1\\) 时后几个草稿很难被全部接受。草稿成本近似线性于 \\(\\gamma\\)（自回归草稿）或线性于树节点。于是存在使净加速最大的 \\(\\gamma^\\star\\)。\\(\\alpha\\) 升高，$ \\gamma^\\star$ 右移。服务若全局锁死 \\(\\gamma=5\\)，在 \\(\\alpha=0.5\\) 的流量上 \\(\\tau=1.97\\)，五步草稿几乎白做。动态 \\(\\gamma\\) 就是在这条曲线上爬坡。",-1)),(l(),n(p,null,{default:t(()=>[i(m,{id:"mermaid-63",class:"mermaid",graph:"flowchart%20TD%0A%20%20G1%5B%22%E7%AC%AC1%E4%B8%AA%E8%8D%89%E7%A8%BF%EF%BC%9A%E6%9C%9F%E6%9C%9B%E8%B4%A1%E7%8C%AE%201%22%5D%20--%3E%20G2%5B%22%E7%AC%AC2%E4%B8%AA%EF%BC%9A%E8%B4%A1%E7%8C%AE%20%CE%B1%EF%BC%88%E5%A6%82%200.5%EF%BC%89%22%5D%0A%20%20G2%20--%3E%20G3%5B%22%E7%AC%AC3%E4%B8%AA%EF%BC%9A%E8%B4%A1%E7%8C%AE%20%CE%B1%C2%B2%EF%BC%88%E5%A6%82%200.25%EF%BC%89%22%5D%0A%20%20G3%20--%3E%20G4%5B%22%E7%AC%AC4%E4%B8%AA%EF%BC%9A%E8%B4%A1%E7%8C%AE%20%CE%B1%C2%B3%EF%BC%88%E5%A6%82%200.125%EF%BC%89%22%5D%0A%20%20G1%20--%3E%20T%5B%22%CF%84%20%3D%20%E5%90%84%E6%9C%9F%E6%9C%9B%E8%B4%A1%E7%8C%AE%E4%B9%8B%E5%92%8C%22%5D%0A%20%20G2%20--%3E%20T%0A%20%20G3%20--%3E%20T%0A%20%20G4%20--%3E%20T%0A%20%20T%20--%3E%20COST%5B%22%E8%8D%89%E7%A8%BF%E6%88%90%E6%9C%AC%E5%8D%B4%E9%9A%8F%20%CE%B3%20%E8%BF%91%E4%BC%BC%E7%BA%BF%E6%80%A7%E4%B8%8A%E6%B6%A8%22%5D%0A%20%20COST%20--%3E%20OPT%5B%22%E5%87%80%E5%8A%A0%E9%80%9F%E5%9C%A8%E4%B8%AD%E9%97%B4%E6%9F%90%E5%A4%84%E6%9C%80%E5%A4%A7%EF%BC%9A%CE%B3*%22%5D%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p>与连续批的交互：Orca 式 iteration-level 调度本就按 iter 插入新请求。投机把一个 iter 的「工作量」变成随机变量。稳定做法是：iter 的时间片按「一次目标前向」来切（校验一次），接受长度只影响本请求的进度，不改变 iter 边界。这样新请求仍能在校验结束后加入，TPOT 方差主要来自 \\(\\alpha\\)，而不是来自偶发的超长草稿循环。</p><p><span class="marginnote">温度为 0 时，接受变成前缀匹配，\\(\\tau\\) 由草稿与目标是否逐步相同决定，公式仍可用，只是 \\(\\alpha\\) 变成「逐步一致率」。评测加速比必须声明温度与采样器，否则和论文表不可比。</span></p><h3 id="和公平、抢占" tabindex="-1">和公平、抢占 <a class="header-anchor" href="#和公平、抢占" aria-label="Permalink to &quot;和公平、抢占&quot;">​</a></h3><p>高 \\(\\alpha\\) 请求每轮前进更多，看起来「更快结束」，低 \\(\\alpha\\) 请求占用同样校验 iter 却少写 token。若计费按输出 token，低 \\(\\alpha\\) 用户更亏算力。公平调度应按「目标前向次数」而不是「输出 token」记账，或给低 \\(\\alpha\\) 请求提高优先级以免饿死。抢占时，未提交草稿一律丢弃，只保留已接受 KV——与 MTP 闭环的提交点相同。</p><p><span class="marginnote">为什么记账单位重要：若按输出 token 计费，低接受率用户每 token 消耗的校验算力可能是高接受率用户的数倍，要么服务方悄悄亏钱，要么这类用户被变相劝退。记账单位选错，后面所有「公平不公平」的讨论都会整体偏掉。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要用训练 perplexity 直接当 \\(\\alpha\\)。不要在树投机里把节点数当成 \\(\\gamma\\) 代入 i.i.d. 公式。不要为抬 \\(\\tau\\) 而放宽拒绝采样，那是在改分布。MTP 的 1.8× 对应浅 \\(\\gamma\\)，接受长度调度的空间有限，更大杠杆在 EAGLE 类可调树。监控若只报吞吐不报 \\(\\alpha\\)，无法判断变慢是模型差了还是 \\(\\gamma\\) 设错了。</p><p>出处：Leviathan 等，<em>Fast Inference from Transformers via Speculative Decoding</em>，ICML 2023，arXiv:2211.17192；Chen 等投机采样；EAGLE-2 动态树；DeepSeek-V3 报告中 MTP 的接受率数字。调度启发式是工程层，不要伪造成 Leviathan 论文里的现成算法名称。</p><p><span class="marginnote">\\(\\alpha\\gt 0.55\\text{–}0.60\\) 一类经验阈值只说明「草稿开销开始赚回来」，依赖草稿/目标成本比，不是定理。换 MTP 这种极便宜草稿，阈值更低；换又慢又不准时的草稿，阈值更高。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>接受长度 \\(\\tau\\) 是投机每轮真正产出的 token 期望，调度应按 \\(\\tau\\) 而不是按「一步一 token」切预算。</li><li>\\(\\gamma\\) 有随 \\(\\alpha\\) 移动的最优值；固定过深会在低接受率上净亏损。</li><li>批内参差、草稿 KV 峰值、按目标前向次数的公平，都由 \\(\\tau\\) 的随机性引出。</li><li>iter 边界应对齐「一次校验」，不要对齐「本轮最长接受」。</li><li>出处：Leviathan 等 ICML 2023；对照 EAGLE-2 与 V3 MTP。</li></ul>',11))])}const f=A(h,[["render",B]]);export{D as __pageData,f as default};
